import{_ as t,c as n,o as a,ae as i}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"ACF Field Integration: Advanced Custom Fields in Ninja Tables","description":"ACF Field Integration: Advanced Custom Fields in Ninja Tables","frontmatter":{"title":"ACF Field Integration: Advanced Custom Fields in Ninja Tables","description":"ACF Field Integration: Advanced Custom Fields in Ninja Tables"},"headers":[],"relativePath":"guide/wordpress-integration/acf-field-integration-with-ninja-tables-column.md","filePath":"guide/wordpress-integration/acf-field-integration-with-ninja-tables-column.md"}'),o={name:"guide/wordpress-integration/acf-field-integration-with-ninja-tables-column.md"};function s(l,e,d,r,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="acf-field-integration-advanced-custom-fields-in-ninja-tables" tabindex="-1">ACF Field Integration: Advanced Custom Fields in Ninja Tables <a class="header-anchor" href="#acf-field-integration-advanced-custom-fields-in-ninja-tables" aria-label="Permalink to &quot;ACF Field Integration: Advanced Custom Fields in Ninja Tables&quot;">​</a></h1><p>**ACF Field **is a versatile feature offered by <strong>Ninja Tables</strong> that improves the capacity of table creation. In this case, ACF means **Advanced Custom Fields, **which enables the table created to be more dynamic. This feature is available when the **WP Post **feature is used in the tables.</p><h2 id="what-is-acf" tabindex="-1">What is ACF<a href="https://wpmanageninja.com/docs/ninja-tables/wp-posts-table/acf-field/#what-is-acf" target="_blank" rel="noreferrer"></a> <a class="header-anchor" href="#what-is-acf" aria-label="Permalink to &quot;What is ACF[](https://wpmanageninja.com/docs/ninja-tables/wp-posts-table/acf-field/#what-is-acf)&quot;">​</a></h2><p>ACF refers to Advanced Custom Fields that make it easier for users to benefit from these custom fields. This feature helps to deal with users’ custom field data and then make it visible to your site’s visitors. Technically, you can add customized information not only to posts and pages but also to categories, taxonomies, custom posts/taxonomies, users, attachments, comments, etc.</p><h2 id="acf-in-ninja-tables" tabindex="-1">ACF in Ninja Tables <a class="header-anchor" href="#acf-in-ninja-tables" aria-label="Permalink to &quot;ACF in Ninja Tables&quot;">​</a></h2><p>This guide demonstrates how to use this feature in Ninja Tables.</p><ul><li>The first step is to install a plugin named <strong>Advanced Custom Field</strong> from the WordPress plugin directory. Next, go to the plugin option on the dashboard&#39;s left sidebar.</li><li>Click on the** Add New **button from the plugin’s dashboard. Then go to the **Add Field **button after giving the title of the new field group. In the input field, enter the <strong>Field Label</strong> &amp; <strong>Field Name</strong>. <img src="https://ninjatables.com/wp-content/uploads/2023/09/ACF-custom-fields-1024x699.png" alt="ACF custom fields"> After that, click on the <strong>Publish/Update</strong> button to publish the post. <img src="https://ninjatables.com/wp-content/uploads/2023/01/ACF-field-integration-3-825x1024.png" alt="ACF field integration field label"> Then a field group gets created. You can add new or edit, move, and delete the ACF fields from the Field Group. <img src="https://ninjatables.com/wp-content/uploads/2023/01/ACF-field-integration-4-1024x257.png" alt="ACF demo"> Then you will notice a new field group has been added to the plugin dashboard. <img src="https://ninjatables.com/wp-content/uploads/2023/01/ACF-field-integration-5.png" alt="ACF new field group"></li><li>Afterward, move to the post where you want to show your custom field using ACF.</li><li>Then, right below the post section, you’ll notice the custom field with an input field from the post page. Add the value that you want to show on the input field on your table. Then, click on the post page’s update button after adding the value. <img src="https://ninjatables.com/wp-content/uploads/2023/09/ACF-field-integration-7.png" alt="Update Post"></li><li>Then, go to the plugin Ninja Tables and click on the Post table generated using the WP Post feature. Select the post table to edit.</li><li>You’ll then be taken to the table interface, where you press the Add Column icon. <img src="https://ninjatables.com/wp-content/uploads/2023/01/ACF-field-integration-9-1024x718.png" alt="ACF add new column"></li><li>You will notice a section of the internal page expanding with its option. You have to add all the required details from there. You’ll then have the Dynamic Post Data Settings option.</li><li>A drop-down menu will be visible, where you will see the <strong>Field Type</strong> Option. Here, select the <strong>Advanced Custom Fields(ACF)</strong> option &amp; enter the respective value in that field. Next, click on the <strong>Add Column</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2023/01/ACF-field-integration-10.png" alt="Advanced Custom Fields"><em>Remember that in the <strong>Field Value</strong> input area, enter the value from the <strong>Name</strong> column in the <strong>Advanced Custom Fields</strong> plugin dashboard according to your created <strong>Field Group</strong>.</em><img src="https://ninjatables.com/wp-content/uploads/2023/01/ACF-field-integration-11-1024x255.png" alt="ACF new custom column"></li><li>After clicking the preview button, you will notice a new custom column, along with its value, gets added to the table. <img src="https://ninjatables.com/wp-content/uploads/2023/01/ACF-field-integration-12.png" alt="Preview"> This is how you can use the <strong>Advanced Custom Fields(ACF)</strong> option of the <strong>Ninja Tables</strong> plugin.</li></ul>',7)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
